on conflict (slug) do nothing;
select id,'pt','EUR',case slug when 'paid-media' then 350 when 'local-visibility' then 250 when 'landing-pages' then 550 when 'email-crm' then 350 when 'digital-review' then 350 else null end,case when slug='paid-media' then 'from_monthly' else 'from_project' end,case slug when 'paid-media' then 'Gestão de media pago.' when 'local-visibility' then 'Google Business e visibilidade local.' when 'landing-pages' then 'Landing page orientada para conversão.' when 'email-crm' then 'Estratégia de email e CRM.' when 'digital-review' then 'Análise de presença digital.' else 'Produção profissional de fotografia e vídeo.' end from public.addons where slug in ('paid-media','local-visibility','photo-video-production','landing-pages','email-crm','digital-review') on conflict (addon_id,market_code) do nothing;
select id,'uk','GBP',case slug when 'paid-media' then 450 when 'local-visibility' then 350 when 'landing-pages' then 750 when 'email-crm' then 450 when 'digital-review' then 450 else null end,case when slug='paid-media' then 'from_monthly' else 'from_project' end,case slug when 'paid-media' then 'Paid media management.' when 'local-visibility' then 'Google Business and local visibility.' when 'landing-pages' then 'Conversion-focused landing page.' when 'email-crm' then 'Email and CRM strategy.' when 'digital-review' then 'Digital presence review.' else 'Professional photography and video production.' end from public.addons where slug in ('paid-media','local-visibility','photo-video-production','landing-pages','email-crm','digital-review') on conflict (addon_id,market_code) do nothing;
